    const drones = this.drones.items;
    for (let j = 0; j < drones.length; j += 1) {
      const d = drones[j];
      if (!d.active) continue;
      if (circlesOverlap(d.x, d.y, d.radius, this.ship.x, this.ship.y, SHIP.hitRadius)) {
        d.active = false;
