  const len = 34;
  const speed = Math.hypot(b.vx, b.vy) || 1;
  const nx = b.vx / speed;
  const ny = b.vy / speed;
  const trail = ctx.createLinearGradient(b.x, b.y, b.x - nx * len, b.y - ny * len);
  trail.addColorStop(0, 'rgba(255, 120, 120, 0.90)');
  trail.addColorStop(0.45, 'rgba(255, 46, 64, 0.55)');
